const prompt = 'You are a professional ATS resume writer. Create a complete tailored ATS-optimized resume as a single clean HTML file.\n\nCANDIDATE PROFILE:\n' + JSON.stringify(profile, null, 2) + '\n\nTARGET COMPANY: ' + company_name + '\n\nJOB DESCRIPTION:\n' + job_description + '\n\nINSTRUCTIONS:\n1. FIXED SECTIONS - copy exactly: name, email, phone, linkedin, github, portfolio, location, education\n2. PROFESSIONAL SUMMARY: Write 3-4 sharp sentences tailored to ' + company_name + ' and this JD.\n3. SKILLS: Pick only relevant skills matching this JD. Group as Technical Skills and Soft Skills.\n4. PROJECTS: Pick the most relevant projects. Rewrite bullets to emphasize JD-matching aspects. Use strong action verbs.\n5. CERTIFICATIONS: Include only relevant certifications for this role.\n6. ATS RULES: Single column only. No images no icons. Standard section names: Summary Skills Projects Certifications Education. JD keywords must appear naturally throughout.\n\nHTML CSS REQUIREMENTS:\nFont Arial sans-serif. Body 11.5px line-height 1.6. Max-width 780px margin auto padding 40px. Name 24px bold centered. Contact line 11px centered separated by pipe symbol. Section headers 12px bold uppercase letter-spacing 1px border-bottom 1.5px solid #222 margin-top 20px. Background white text #1a1a1a. Include media print. All in one HTML file with CSS in style tag.\n\nOUTPUT: Return ONLY raw HTML starting with <!DOCTYPE html>. No markdown no backticks no explanation.';

return [{ json: { prompt, company_name } }];

